// offline cache for the solitaire collection (generated by web/tools/pwa.py; version = hash of the files)
const CACHE='solitaire-40d8bb176153',ASSETS=["./", "index.html", "icon-192.png", "icon-512.png", "icon-maskable-512.png", "manifest.webmanifest"];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k.startsWith('solitaire-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
// cache first: the game never waits for the network; a page navigation falls back to the cached index.html
self.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;
 e.respondWith(caches.match(e.request,{ignoreSearch:true}).then(r=>r||(e.request.mode==='navigate'?caches.match('index.html'):fetch(e.request))))});
